  proof=row.get('verified_evidence',[])
  if row['status'].startswith(('aggregate_review_scope','semantic_artifact_audit','snapshot_removal')):proof=proof+row.get('declared_evidence',[])
  for e in proof:
   for key,value in e.items():
    if isinstance(value,str) and value.startswith('/tmp/') and value.endswith(('.json','.md')):review_refs[value].add((c['number'],row['path']))
review_inputs=[]
for path,records in sorted(review_refs.items()):
 p=Path(path);row={'recorded_location':path,'exists_now':p.is_file(),'current_commit_path_mentions':len(records),'records':[{'commit':n,'path':q} for n,q in sorted(records)],'durable_destination':'raised-energy-cff-stack-evidence.json: stable record with preserved scope/proof and input hash; coverage refers to that stable ID.'}
 if p.is_file():bs=p.read_bytes();row.update(bytes=len(bs),sha256=hashlib.sha256(bs).hexdigest())
 review_inputs.append(row)

